<?php
session_start();
require_once '../config/database.php';
require_once 'lib.php';
require_once 'generator.php';
require_once 'assignment_service.php';
function ttLoadAssignmentPreparedCut(PDO$pdo,array$assignment,int$railroadId,bool$lock=false):?array{$id=(int)($assignment['prepared_cut_id']??0);if(($assignment['start_method']??'')!=='prepared_cut'||$id<=0)return null;$sql="SELECT c.*,i.industry_name,(SELECT COUNT(*) FROM prepared_cut_cars pc WHERE pc.prepared_cut_id=c.id) car_count FROM prepared_cuts c JOIN industries i ON i.id=c.current_industry_id AND i.railroad_id=c.railroad_id WHERE c.id=? AND c.railroad_id=?".($lock?' FOR UPDATE':'');$stmt=$pdo->prepare($sql);$stmt->execute([$id,$railroadId]);$cut=$stmt->fetch(PDO::FETCH_ASSOC)?:null;if(!ttPreparedCutStatusIsAssigned($cut)){http_response_code(409);throw new RuntimeException('The prepared cut is no longer assigned to this assignment. Restore or replace the cut before generating a switch list.');}return$cut;}
function ttLoadJobRouteAreas(PDO $pdo,int $jobId,int $railroadId):array{$stmt=$pdo->prepare("SELECT jrs.*,COALESCE(jop.work_scope,'entire_railroad') work_scope,i.id expanded_industry_id,i.industry_name,legacy_i.location legacy_location FROM jobs j LEFT JOIN job_operation_profiles jop ON jop.job_id=j.id AND jop.railroad_id=j.railroad_id LEFT JOIN job_route_stops jrs ON jrs.job_id=j.id AND jrs.railroad_id=j.railroad_id LEFT JOIN industries legacy_i ON legacy_i.id=jrs.industry_id AND legacy_i.railroad_id=jrs.railroad_id LEFT JOIN industries i ON i.railroad_id=jrs.railroad_id AND i.active=1 AND NULLIF(TRIM(jrs.operating_area),'') IS NOT NULL AND TRIM(i.location)=TRIM(jrs.operating_area) WHERE j.id=? AND j.railroad_id=? ORDER BY jrs.sequence_number,i.industry_name,i.id");$stmt->execute([$jobId,$railroadId]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);$stops=[];$empty=[];foreach($rows as$row){$routeStopId=(int)($row['id']??0);if(!$routeStopId)continue;$label=trim((string)($row['operating_area']??''));if($label==='')continue;if((int)($row['expanded_industry_id']??0)>0){$row['industry_id']=(int)$row['expanded_industry_id'];$stops[]=$row;}else{$empty[]=$label;}}return ['stops'=>$stops,'empty_areas'=>array_values(array_unique($empty)),'work_scope'=>$rows[0]['work_scope']??'entire_railroad'];}
if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}
$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$railroadId=(int)$railroad['id'];$assignmentId=(int)($_GET['assignment_id']??$_POST['assignment_id']??0);
if($assignmentId<=0){header('Location: sessions.php');exit;}
$stmt=$pdo->prepare('SELECT a.*,s.session_number,s.session_name,s.status session_status,b.industry_name base_name FROM operation_assignments a JOIN operating_sessions s ON s.id=a.session_id AND s.railroad_id=a.railroad_id LEFT JOIN industries b ON b.id=a.operating_base_industry_id AND b.railroad_id=a.railroad_id WHERE a.id=? AND a.railroad_id=?');$stmt->execute([$assignmentId,$railroadId]);$assignment=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$assignment){http_response_code(404);die('Assignment not found.');}$error='';
$listStatuses=ttAssignmentListStatuses($pdo,$assignmentId,$railroadId);if(!ttAssignmentCanGenerate($assignment,$listStatuses)){http_response_code(409);die('Switch-list generation is blocked because the session or assignment is frozen, inheritance is unsupported, or an approved/active/historical review revision exists.');}

$routeData=ttLoadJobRouteAreas($pdo,(int)$assignment['job_template_id'],$railroadId);$routeStops=$routeData['stops'];$emptyRouteAreas=$routeData['empty_areas'];$assignment['work_scope']=$routeData['work_scope'];$selectedRouteMissingStops=$assignment['work_scope']==='selected_route'&&(!$routeStops||$emptyRouteAreas);$routeAreaLabels=ttRouteAreaLabels($routeStops);
try{$preparedCut=ttLoadAssignmentPreparedCut($pdo,$assignment,$railroadId);}catch(RuntimeException$e){http_response_code(409);die(ttHtml($e->getMessage()));}
$startingCountStmt=$pdo->prepare('SELECT COUNT(*) FROM operation_assignment_starting_cars WHERE assignment_id=?');$startingCountStmt->execute([$assignmentId]);$startingTrainCount=(int)$startingCountStmt->fetchColumn();

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        ttOperationsRequireCsrf();
        $pdo->beginTransaction();
        $sessionLock=$pdo->prepare('SELECT status FROM operating_sessions WHERE id=? AND railroad_id=? FOR UPDATE');$sessionLock->execute([(int)$assignment['session_id'],$railroadId]);$sessionStatus=$sessionLock->fetchColumn();
        $assignmentLock=$pdo->prepare('SELECT a.*,b.industry_name base_name FROM operation_assignments a LEFT JOIN industries b ON b.id=a.operating_base_industry_id AND b.railroad_id=a.railroad_id WHERE a.id=? AND a.railroad_id=? FOR UPDATE');$assignmentLock->execute([$assignmentId,$railroadId]);$assignment=$assignmentLock->fetch(PDO::FETCH_ASSOC);if(!$assignment)throw new RuntimeException('Assignment not found.');$assignment['session_status']=(string)$sessionStatus;
        $routeData=ttLoadJobRouteAreas($pdo,(int)$assignment['job_template_id'],$railroadId);$routeStops=$routeData['stops'];$emptyRouteAreas=$routeData['empty_areas'];$assignment['work_scope']=$routeData['work_scope'];$selectedRouteMissingStops=$assignment['work_scope']==='selected_route'&&(!$routeStops||$emptyRouteAreas);$routeAreaLabels=ttRouteAreaLabels($routeStops);$preparedCut=ttLoadAssignmentPreparedCut($pdo,$assignment,$railroadId,true);if($preparedCut){$assignment['prepared_cut_industry_id']=(int)$preparedCut['current_industry_id'];$assignment['prepared_cut_track']=(string)$preparedCut['current_track'];}
        $revisionSummary=ttSwitchListRevisionSummary($pdo,$assignmentId,$railroadId,true);if(!ttAssignmentCanGenerate($assignment,$revisionSummary['statuses'])){http_response_code(409);throw new RuntimeException('Switch-list generation was blocked because the session, assignment, or retained revision state changed.');}
        if($selectedRouteMissingStops)throw new RuntimeException($emptyRouteAreas?'These selected Route Areas contain no active industries: '.implode(', ',$emptyRouteAreas).'. Update Industry Location values or edit the Job Title route.':'This Job Title has no valid Operating Areas. Add at least one Route Area or change the scope to Entire Railroad.');
        $reserved=ttReservedEquipmentIds($pdo,$railroadId,$assignmentId);
        $startingStmt=$pdo->prepare('SELECT equipment_id,source_type,source_id FROM operation_assignment_starting_cars WHERE assignment_id=? ORDER BY position FOR UPDATE');$startingStmt->execute([$assignmentId]);$startingRows=$startingStmt->fetchAll(PDO::FETCH_ASSOC);if($preparedCut){foreach($startingRows as$startingRow)if(($startingRow['source_type']??'')!=='prepared_cut'||(int)($startingRow['source_id']??0)!==(int)$preparedCut['id']){http_response_code(409);throw new RuntimeException('The prepared cut starting-car membership no longer matches this assignment. Restore or replace the cut before generating a switch list.');}}$startingIds=array_map(static fn($row)=>(int)$row['equipment_id'],$startingRows);if($preparedCut)$preparedCut['car_count']=count($startingIds);
        $carsStmt=$pdo->prepare("SELECT e.id,e.reporting_marks,e.road_number,e.equipment_type,e.operations_service,e.load_status,e.current_industry_id,e.current_track,e.photo_filename,i.industry_name origin_name FROM equipment e JOIN industries i ON i.id=e.current_industry_id WHERE e.railroad_id=? AND e.active=1 AND COALESCE(e.equipment_class,'')<>'Locomotive' ORDER BY e.reporting_marks,e.road_number FOR UPDATE");$carsStmt->execute([$railroadId]);$cars=$carsStmt->fetchAll(PDO::FETCH_ASSOC);
        $industriesStmt=$pdo->prepare('SELECT id,industry_name,industry_type,location,receives_services,ships_services,track_capacity FROM industries WHERE railroad_id=? AND active=1 ORDER BY industry_name');$industriesStmt->execute([$railroadId]);$industries=$industriesStmt->fetchAll(PDO::FETCH_ASSOC);
        $plan=ttChooseOperationsMoves($assignment,$cars,$industries,$startingIds,$reserved,$routeStops);
        $revision=(int)$revisionSummary['max_revision']+1;ttCancelDraftSwitchLists($pdo,$assignmentId,$railroadId,'Superseded by Revision '.$revision.'.');
        $insert=$pdo->prepare("INSERT INTO operation_switch_lists(railroad_id,session_id,assignment_id,switch_list_number,revision_number,status,generated_by_user_id,planned_move_count,diagnostic_summary) VALUES(?,?,?,?,?,'draft',?,?,?)");$insert->execute([$railroadId,(int)$assignment['session_id'],$assignmentId,$assignment['assignment_number'],$revision,(int)$_SESSION['user_id'],count($plan['moves']),implode("\n",$plan['diagnostics'])]);$listId=(int)$pdo->lastInsertId();
        $moveInsert=$pdo->prepare('INSERT INTO operation_switch_list_moves(switch_list_id,railroad_id,sequence_number,movement_group,equipment_id,reporting_marks_snapshot,road_number_snapshot,equipment_type_snapshot,service_snapshot,photo_filename_snapshot,original_load_status,planned_load_status,origin_industry_id,origin_name_snapshot,origin_track,destination_industry_id,destination_name_snapshot,destination_track,action,instruction,work_location) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$sequence=1;
        if($preparedCut){$pickupInstruction=ttPreparedCutPickupInstruction($assignment,$preparedCut);$moveInsert->execute([$listId,$railroadId,$sequence++,'instruction-pickup',null,null,null,null,null,null,null,null,(int)$assignment['operating_base_industry_id'],$assignment['base_name'],$assignment['starting_track'],(int)$preparedCut['current_industry_id'],$preparedCut['industry_name'],$preparedCut['current_track'],'PICKUP',$pickupInstruction,'Prepared cut pickup']);}
        $lastWorkLocation=null;
        foreach($plan['moves']as$move){
            if($move['work_location']!==$lastWorkLocation){$lastWorkLocation=$move['work_location'];$moveInsert->execute([$listId,$railroadId,$sequence++,'location-'.bin2hex(random_bytes(6)),null,null,null,null,null,null,null,null,null,null,null,null,null,null,'LOCATION',strtoupper((string)$lastWorkLocation),(string)$lastWorkLocation]);}
            $moveInsert->execute([$listId,$railroadId,$sequence++,$move['movement_group'],$move['equipment_id'],$move['reporting_marks_snapshot'],$move['road_number_snapshot'],$move['equipment_type_snapshot'],$move['service_snapshot'],$move['photo_filename_snapshot'],$move['original_load_status'],$move['planned_load_status'],$move['origin_industry_id'],$move['origin_name_snapshot'],$move['origin_track'],$move['destination_industry_id'],$move['destination_name_snapshot'],$move['destination_track'],$move['action'],$move['instruction'],$move['work_location']]);
        }
        $pdo->commit();header('Location: work_order.php?id='.$listId);exit;
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$latest=$pdo->prepare("SELECT * FROM operation_switch_lists WHERE assignment_id=? AND railroad_id=? AND status<>'cancelled' ORDER BY revision_number DESC LIMIT 1");$latest->execute([$assignmentId,$railroadId]);$latest=$latest->fetch(PDO::FETCH_ASSOC);
?>
<?php include '../includes/header.php';?><title>Generate <?=ttHtml($assignment['assignment_number'])?></title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page"><p class="tt-eyebrow"><?=ttHtml($assignment['session_number'].' · '.$assignment['assignment_number'])?></p><h1>Generate Switch List</h1><p class="lead"><?=ttHtml($assignment['title_snapshot'])?></p><?php if($error):?><div class="alert alert-danger"><?=ttHtml($error)?></div><?php endif;?><?php if($selectedRouteMissingStops):?><div class="alert alert-warning"><?=ttHtml($emptyRouteAreas?'These selected Route Areas contain no active industries: '.implode(', ',$emptyRouteAreas).'.':'This Job Title has no valid Operating Areas. Add at least one Route Area or change the scope to Entire Railroad.')?></div><?php endif;?><div class="card mb-4"><div class="card-body"><dl class="row"><dt class="col-sm-4">Work scope</dt><dd class="col-sm-8"><?=$assignment['work_scope']==='selected_route'?'Selected Route / Territory':'Entire Railroad'?></dd><?php if($assignment['work_scope']==='selected_route'):?><dt class="col-sm-4">Route Areas</dt><dd class="col-sm-8"><?=ttHtml(implode(' → ',$routeAreaLabels)?:'None')?></dd><?php endif;?><dt class="col-sm-4">Operating pattern</dt><dd class="col-sm-8"><?=ttHtml(ttJobTypes()[$assignment['operating_pattern']]??$assignment['operating_pattern'])?></dd><?php if($preparedCut):?><dt class="col-sm-4">Prepared Cut</dt><dd class="col-sm-8"><?=ttHtml($preparedCut['cut_number'].' — '.$preparedCut['name'])?></dd><dt class="col-sm-4">Starting train</dt><dd class="col-sm-8"><?=$startingTrainCount?> cars</dd><dt class="col-sm-4">Pickup location</dt><dd class="col-sm-8"><?=ttHtml($preparedCut['industry_name'].($preparedCut['current_track']!==''?' / '.$preparedCut['current_track']:''))?></dd><dt class="col-sm-4">Prepared cut cars to switch</dt><dd class="col-sm-8">Up to <?=(int)$assignment['prepared_cut_car_count']?>; invalid work is never invented</dd><dt class="col-sm-4">Maximum additional pickups</dt><dd class="col-sm-8"><?=(int)$assignment['requested_car_count']?></dd><?php else:?><dt class="col-sm-4">Cars to switch</dt><dd class="col-sm-8">Up to <?=(int)$assignment['requested_car_count']?>; invalid work is never invented</dd><?php endif;?></dl><?php if($latest):?><p>Latest saved revision: <a href="work_order.php?id=<?=(int)$latest['id']?>"><?=ttHtml($latest['switch_list_number'])?> — Revision <?=(int)$latest['revision_number']?> (<?=ttHtml($latest['status'])?>)</a></p><?php endif;?></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><input type="hidden" name="assignment_id" value="<?=$assignmentId?>"><button class="btn btn-primary" <?=$selectedRouteMissingStops?'disabled':''?>><?php if($latest):?>Regenerate Switch List<?php else:?>Generate Switch List<?php endif;?></button> <a class="btn btn-secondary" href="session_edit.php?id=<?=(int)$assignment['session_id']?>">Back to Session</a> <a class="btn btn-outline-secondary" href="assignment_edit.php?id=<?=$assignmentId?>">Edit Assignment</a><?php if($selectedRouteMissingStops):?> <a class="btn btn-outline-primary" href="../jobs/route.php?id=<?=(int)$assignment['job_template_id']?>">Edit Route</a><?php endif;?></form></section></div><?php include '../includes/footer.php';?>
